#include <iostream>
#include <iomanip>

class Time {
public:
    explicit Time(int hr = 0, int min = 0, int sec = 0) {
        setTime(hr, min, sec);
    }

    Time& setTime(int h, int m, int s) {
        setHour(h);
        setMinute(m);
        setSecond(s);
        return *this;
    }

    Time& setHour(int h) {
        hour = (h >= 0 && h < 24) ? h : 0;
        return *this;
    }

    Time& setMinute(int m) {
        minute = (m >= 0 && m < 60) ? m : 0;
        return *this;
    }

    Time& setSecond(int s) {
        second = (s >= 0 && s < 60) ? s : 0;
        return *this;
    }

    void printUniversal() const {
        std::cout << std::setfill('0') << std::setw(2) << hour << ":"
                  << std::setw(2) << minute << ":" << std::setw(2) << second;
    }

    void printStandard() const {
        std::cout << ((hour == 0 || hour == 12) ? 12 : hour % 12) << ":"
                  << std::setfill('0') << std::setw(2) << minute << ":"
                  << std::setw(2) << second << (hour < 12 ? " AM" : " PM");
    }

private:
    int hour{0};
    int minute{0};
    int second{0};
};

int main() {
    Time t;
    t.setHour(18).setMinute(30).setSecond(22);

    std::cout << "Universal time: ";
    t.printUniversal();
    std::cout << "\nStandard time: ";
    t.printStandard();

    std::cout << "\n\nNew standard time: ";
    t.setTime(20, 20, 20).printStandard();
    std::cout << std::endl;

    return 0;
}

#include <iostream>
#include <string>

class Employee {
public:
    Employee(const std::string& first, const std::string& last)
        : firstName(first), lastName(last) {
        ++count;
        std::cout << "Employee constructor for " << firstName << ' ' << lastName << " called.\n";
    }

    ~Employee() {
        std::cout << "~Employee() called for " << firstName << ' ' << lastName << "\n";
        --count;
    }

    std::string getFirstName() const { return firstName; }
    std::string getLastName() const { return lastName; }

    static unsigned int getCount() {
        return count;
    }

private:
    std::string firstName;
    std::string lastName;
    static unsigned int count;
};

// Definition and initialization outside class definition (C++ standard requirement)
unsigned int Employee::count = 0;

int main() {
    std::cout << "Number of employees before instantiation: "
              << Employee::getCount() << "\n";

    {
        Employee e1("Susan", "Baker");
        Employee e2("Robert", "Jones");

        std::cout << "Number of employees after objects are instantiated: "
                  << Employee::getCount() << "\n\n";

        std::cout << "Employee 1: " << e1.getFirstName() << " " << e1.getLastName()
                  << "\nEmployee 2: " << e2.getFirstName() << " " << e2.getLastName() << "\n\n";
    }

    std::cout << "\nNumber of employees after objects are deleted: "
              << Employee::getCount() << std::endl;

    return 0;
}
